frappe.ui.form.on('Attendance Request', {
    validate(frm) {

    },

    from_date: function(frm){
        let no_of_days = moment(frm.doc.to_date).diff(frm.doc.from_date, 'days');

        if (no_of_days > 1) {
            frm.set_df_property("custom_from_time", "hidden", 1);
            frm.set_df_property("custom_to_time", "hidden", 1);
        } else {
            frm.set_df_property("custom_from_time", "hidden", 0);
            frm.set_df_property("custom_to_time", "hidden", 0);
        }        
    },

    to_date: function(frm) {
        let no_of_days = moment(frm.doc.to_date).diff(frm.doc.from_date, 'days');

        if (no_of_days > 1) {
            frm.set_df_property("custom_from_time", "hidden", 1);
            frm.set_df_property("custom_to_time", "hidden", 1);
        } else {
            frm.set_df_property("custom_from_time", "hidden", 0);
            frm.set_df_property("custom_to_time", "hidden", 0);
        }

    },

    before_workflow_action: (frm) => {
        console.log(frm.selected_workflow_action);

        if (frm.selected_workflow_action == "Reject") {
            let dialog = new frappe.ui.Dialog({
                    title: 'Reason for Rejection',
                    fields: [
                        {
                            label: 'Reason',
                            fieldname: 'reject_reason',
                            fieldtype: 'Link',
                            options: 'Reject Reason',
                            reqd: 1,
                            get_query: function() {
                                return {
                                    filters: [
                                        ["Reject Reason Type", "document_type", "=", frm.doc.doctype]
                                    ]
                                };
                            }
                        }
                    ],
                    primary_action_label: 'Reject',
                    primary_action(values) {
                        if (values.reject_reason) {

                            frappe.call({
                                method: 'set_reject_reason',
                                args: {
                                    doctype: frm.doc.doctype,
                                    doc_name :frm.doc.name,
                                    reject_reason: values.reject_reason,
                                    workflow_state: frm.doc.workflow_state,
                                    freeze: true,
                                }
                            }).then(res=>{
                                if(res.status == "false"){
                                    frappe.throw(res.message.message);
                                }else{
                                    frappe.msgprint(res.message.message);
                                    setTimeout(function() {
                                        window.location.reload();
                                    }, 2000);
                                }
                            });

                        dialog.hide();
                    }
                }
                });
            dialog.show();
        }
    },

});

